@Test
public void testStatementLifecycle() throws Exception {
    ConnectionSpec.getDatabaseLock().lock();
    try (AvaticaConnection connection = (AvaticaConnection) getLocalConnection()) {
        Map<Integer, AvaticaStatement> clientMap = connection.statementMap;
        Cache<Integer, Object> serverMap = getLocalConnectionInternals().getRemoteStatementMap(connection);
        // Other tests being run might leave statements in the cache.
        // The lock guards against more statements being cached during the test.
        serverMap.invalidateAll();
        assertEquals(0, clientMap.size());
        assertEquals(0, serverMap.size());
        Statement stmt = connection.createStatement();
        assertEquals(1, clientMap.size());
        assertEquals(1, serverMap.size());
        stmt.close();
        assertEquals(0, clientMap.size());
        assertEquals(0, serverMap.size());
    } finally {
        ConnectionSpec.getDatabaseLock().unlock();
    }
}

@Test
public void testConnectionIsolation() throws Exception {
    ConnectionSpec.getDatabaseLock().lock();
    try {
        Cache<String, Connection> connectionMap = getLocalConnectionInternals().getRemoteConnectionMap((AvaticaConnection) getLocalConnection());
        // Other tests being run might leave connections in the cache.
        // The lock guards against more connections being cached during the test.
        connectionMap.invalidateAll();
        final String sql = "select * from (values (1, 'a'))";
        assertEquals("connection cache should start empty", 0, connectionMap.size());
        Connection conn1 = getLocalConnection();
        Connection conn2 = getLocalConnection();
        assertEquals("we now have two connections open", 2, connectionMap.size());
        PreparedStatement conn1stmt1 = conn1.prepareStatement(sql);
        assertEquals("creating a statement does not cause new connection", 2, connectionMap.size());
        PreparedStatement conn2stmt1 = conn2.prepareStatement(sql);
        assertEquals("creating a statement does not cause new connection", 2, connectionMap.size());
        AvaticaPreparedStatement s1 = (AvaticaPreparedStatement) conn1stmt1;
        AvaticaPreparedStatement s2 = (AvaticaPreparedStatement) conn2stmt1;
        assertFalse("connection id's should be unique", s1.handle.connectionId.equalsIgnoreCase(s2.handle.connectionId));
        conn2.close();
        assertEquals("closing a connection closes the server-side connection", 1, connectionMap.size());
        conn1.close();
        assertEquals("closing a connection closes the server-side connection", 0, connectionMap.size());
    } finally {
        ConnectionSpec.getDatabaseLock().unlock();
    }
}

