/**
 * Unit test for {@link RelCollations#contains}.
 */
@Test
public void testCollationContains() {
    final RelCollation collation = RelCollations.of(new RelFieldCollation(2, RelFieldCollation.Direction.ASCENDING), new RelFieldCollation(1, RelFieldCollation.Direction.DESCENDING));
    assertThat(RelCollations.contains(collation, Arrays.asList(2)), is(true));
    assertThat(RelCollations.contains(collation, Arrays.asList(1)), is(false));
    assertThat(RelCollations.contains(collation, Arrays.asList(0)), is(false));
    assertThat(RelCollations.contains(collation, Arrays.asList(2, 1)), is(true));
    assertThat(RelCollations.contains(collation, Arrays.asList(2, 0)), is(false));
    assertThat(RelCollations.contains(collation, Arrays.asList(2, 1, 3)), is(false));
    assertThat(RelCollations.contains(collation, Arrays.<Integer>asList()), is(true));
}

/**
 * Unit test for
 *  {@link org.apache.calcite.rel.RelCollationImpl#compareTo}.
 */
@Test
public void testCollationCompare() {
    assertThat(collation(1, 2).compareTo(collation(1, 2)), equalTo(0));
    assertThat(collation(1, 2).compareTo(collation(1)), equalTo(1));
    assertThat(collation(1).compareTo(collation(1, 2)), equalTo(-1));
    assertThat(collation(1, 3).compareTo(collation(1, 2)), equalTo(1));
    assertThat(collation(0, 3).compareTo(collation(1, 2)), equalTo(-1));
    assertThat(collation().compareTo(collation(0)), equalTo(-1));
    assertThat(collation(1).compareTo(collation()), equalTo(1));
}

/**
 * Tests an executor that uses variables stored in a {@link DataContext}.
 * Can change the value of the variable and execute again.
 */
@Test
public void testVariableExecution() throws Exception {
    check(new Action() {

        public void check(RexBuilder rexBuilder, RexExecutorImpl executor) {
            Object[] values = new Object[1];
            final DataContext testContext = new TestDataContext(values);
            final RelDataTypeFactory typeFactory = rexBuilder.getTypeFactory();
            final RelDataType varchar = typeFactory.createSqlType(SqlTypeName.VARCHAR);
            final RelDataType integer = typeFactory.createSqlType(SqlTypeName.INTEGER);
            // Calcite is internally creating the input ref via a RexRangeRef
            // which eventually leads to a RexInputRef. So we are good.
            final RexInputRef input = rexBuilder.makeInputRef(varchar, 0);
            final RexNode lengthArg = rexBuilder.makeLiteral(3, integer, true);
            final RexNode substr = rexBuilder.makeCall(SqlStdOperatorTable.SUBSTRING, input, lengthArg);
            ImmutableList<RexNode> constExps = ImmutableList.of(substr);
            final RelDataType rowType = typeFactory.builder().add("someStr", varchar).build();
            final RexExecutable exec = executor.getExecutable(rexBuilder, constExps, rowType);
            exec.setDataContext(testContext);
            values[0] = "Hello World";
            Object[] result = exec.execute();
            assertTrue(result[0] instanceof String);
            assertThat((String) result[0], equalTo("llo World"));
            values[0] = "Calcite";
            result = exec.execute();
            assertTrue(result[0] instanceof String);
            assertThat((String) result[0], equalTo("lcite"));
        }
    });
}

