@Test
public void testLikeAndSimilar() {
    check("select * from t where x like '%abc%'", "SELECT *\n" + "FROM `T`\n" + "WHERE (`X` LIKE '%abc%')");
    check("select * from t where x+1 not siMilaR to '%abc%' ESCAPE 'e'", "SELECT *\n" + "FROM `T`\n" + "WHERE ((`X` + 1) NOT SIMILAR TO '%abc%' ESCAPE 'e')");
    // LIKE has higher precedence than AND
    check("select * from t where price > 5 and x+2*2 like y*3+2 escape (select*from t)", "SELECT *\n" + "FROM `T`\n" + "WHERE ((`PRICE` > 5) AND ((`X` + (2 * 2)) LIKE ((`Y` * 3) + 2) ESCAPE (SELECT *\n" + "FROM `T`)))");
    check("values a and b like c", "VALUES (ROW((`A` AND (`B` LIKE `C`))))");
    // LIKE has higher precedence than AND
    check("values a and b like c escape d and e", "VALUES (ROW(((`A` AND (`B` LIKE `C` ESCAPE `D`)) AND `E`)))");
    // LIKE has same precedence as '='; LIKE is right-assoc, '=' is left
    check("values a = b like c = d", "VALUES (ROW(((`A` = `B`) LIKE (`C` = `D`))))");
    // Nested LIKE
    check("values a like b like c escape d", "VALUES (ROW((`A` LIKE (`B` LIKE `C` ESCAPE `D`))))");
    check("values a like b like c escape d and false", "VALUES (ROW(((`A` LIKE (`B` LIKE `C` ESCAPE `D`)) AND FALSE)))");
    check("values a like b like c like d escape e escape f", "VALUES (ROW((`A` LIKE (`B` LIKE (`C` LIKE `D` ESCAPE `E`) ESCAPE `F`))))");
    // Mixed LIKE and SIMILAR TO
    check("values a similar to b like c similar to d escape e escape f", "VALUES (ROW((`A` SIMILAR TO (`B` LIKE (`C` SIMILAR TO `D` ESCAPE `E`) ESCAPE `F`))))");
    // FIXME should fail at "escape"
    checkFails("select * from t ^where^ escape 'e'", "(?s).*Encountered \"where escape\" at .*");
    // LIKE with +
    check("values a like b + c escape d", "VALUES (ROW((`A` LIKE (`B` + `C`) ESCAPE `D`)))");
    // LIKE with ||
    check("values a like b || c escape d", "VALUES (ROW((`A` LIKE (`B` || `C`) ESCAPE `D`)))");
    // ESCAPE with no expression
    // FIXME should fail at "escape"
    checkFails("values a ^like^ escape d", "(?s).*Encountered \"like escape\" at .*");
    // ESCAPE with no expression
    checkFails("values a like b || c ^escape^ and false", "(?s).*Encountered \"escape and\" at line 1, column 22.*");
    // basic SIMILAR TO
    check("select * from t where x similar to '%abc%'", "SELECT *\n" + "FROM `T`\n" + "WHERE (`X` SIMILAR TO '%abc%')");
    check("select * from t where x+1 not siMilaR to '%abc%' ESCAPE 'e'", "SELECT *\n" + "FROM `T`\n" + "WHERE ((`X` + 1) NOT SIMILAR TO '%abc%' ESCAPE 'e')");
    // SIMILAR TO has higher precedence than AND
    check("select * from t where price > 5 and x+2*2 SIMILAR TO y*3+2 escape (select*from t)", "SELECT *\n" + "FROM `T`\n" + "WHERE ((`PRICE` > 5) AND ((`X` + (2 * 2)) SIMILAR TO ((`Y` * 3) + 2) ESCAPE (SELECT *\n" + "FROM `T`)))");
    // Mixed LIKE and SIMILAR TO
    check("values a similar to b like c similar to d escape e escape f", "VALUES (ROW((`A` SIMILAR TO (`B` LIKE (`C` SIMILAR TO `D` ESCAPE `E`) ESCAPE `F`))))");
    // SIMILAR TO with subquery
    check("values a similar to (select * from t where a like b escape c) escape d", "VALUES (ROW((`A` SIMILAR TO (SELECT *\n" + "FROM `T`\n" + "WHERE (`A` LIKE `B` ESCAPE `C`)) ESCAPE `D`)))");
}

