    check("select a from foo order by b, c offset 1 rows fetch first 2 rows only", "SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 2 ROWS ONLY");
    // as above, but NEXT (means same as FIRST)
    check("select a from foo order by b, c offset 1 rows fetch next 3 rows only", "SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 3 ROWS ONLY");
    // as above, but omit the ROWS noise word after OFFSET. This is not
    // compatible with SQL:2008 but allows the Postgres syntax
    // "LIMIT ... OFFSET".
    check("select a from foo order by b, c offset 1 fetch next 3 rows only", "SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 3 ROWS ONLY");
    // as above, omit OFFSET
    check("select a from foo order by b, c fetch next 3 rows only", "SELECT `A`
" + "FROM `FOO`
" + "ORDER BY `B`, `C`
" + "FETCH NEXT 3 ROWS ONLY");
    // FETCH, no ORDER BY or OFFSET
    check("select a from foo fetch next 4 rows only", "SELECT `A`
" + "FROM `FOO`
" + "FETCH NEXT 4 ROWS ONLY");
    // OFFSET, no ORDER BY or FETCH
    check("select a from foo offset 1 row", "SELECT `A`
" + "FROM `FOO`
" + "OFFSET 1 ROWS");
    // OFFSET and FETCH, no ORDER BY
    check("select a from foo offset 1 row fetch next 3 rows only", "SELECT `A`
" + "FROM `FOO`
" + "OFFSET 1 ROWS
" + "FETCH NEXT 3 ROWS ONLY");
    // missing ROWS after FETCH
    checkFails("select a from foo offset 1 fetch next 3 ^only^", "(?s).*Encountered "only" at .*");
    // FETCH before OFFSET is illegal
    checkFails("select a from foo fetch next 3 rows only ^offset^ 1", "(?s).*Encountered "offset" at .*");
}

