@Test
public void testWindowSpec() {
    // Correct syntax
    check("select count(z) over w as foo from Bids window w as (partition by y + yy, yyy order by x rows between 2 preceding and 2 following)", "SELECT (COUNT(`Z`) OVER `W`) AS `FOO`\n" + "FROM `BIDS`\n" + "WINDOW `W` AS (PARTITION BY (`Y` + `YY`), `YYY` ORDER BY `X` ROWS BETWEEN 2 PRECEDING AND 2 FOLLOWING)");
    check("select count(*) over w from emp window w as (rows 2 preceding)", "SELECT (COUNT(*) OVER `W`)\n" + "FROM `EMP`\n" + "WINDOW `W` AS (ROWS 2 PRECEDING)");
    // Chained string literals are valid syntax. They are unlikely to be
    // semantically valid, because intervals are usually numeric or
    // datetime.
    // Note: literal chain is not yet replaced with combined literal
    // since we are just parsing, and not validating the sql.
    check("select count(*) over w from emp window w as (\n" + "  rows 'foo' 'bar'\n" + "       'baz' preceding)", "SELECT (COUNT(*) OVER `W`)\n" + "FROM `EMP`\n" + "WINDOW `W` AS (ROWS 'foo'\n'bar'\n'baz' PRECEDING)");
    // Partition clause out of place. Found after ORDER BY
    checkFails("select count(z) over w as foo \n" + "from Bids window w as (partition by y order by x ^partition^ by y)", "(?s).*Encountered \"partition\".*");
    checkFails("select count(z) over w as foo from Bids window w as (order by x ^partition^ by y)", "(?s).*Encountered \"partition\".*");
    // Cannot partition by subquery
    checkFails("select sum(a) over (partition by ^(^select 1 from t), x) from t2", "Query expression encountered in illegal context");
    // AND is required in BETWEEN clause of window frame
    checkFails("select sum(x) over (order by x range between unbounded preceding ^unbounded^ following)", "(?s).*Encountered \"unbounded\".*");
    // WINDOW keyword is not permissible.
    // FIXME should fail at "window"
    checkFails("select sum(x) ^over^ window (order by x) from bids", "(?s).*Encountered \"over window\".*");
    // ORDER BY must be before Frame spec
    checkFails("select sum(x) over (rows 2 preceding ^order^ by x) from emp", "(?s).*Encountered \"order\".*");
}

