    sql("select 1 + next value for s + current value for s from t").ok("SELECT ((1 + (NEXT VALUE FOR `S`)) + (CURRENT VALUE FOR `S`))
" + "FROM `T`");
    sql("select 1 from t where next value for my_seq < 10").ok("SELECT 1
" + "FROM `T`
" + "WHERE ((NEXT VALUE FOR `MY_SEQ`) < 10)");
    sql("select 1 from t
" + "where next value for my_seq < 10 fetch next 3 rows only").ok("SELECT 1
" + "FROM `T`
" + "WHERE ((NEXT VALUE FOR `MY_SEQ`) < 10)
" + "FETCH NEXT 3 ROWS ONLY");
    sql("insert into t values next value for my_seq, current value for my_seq").ok("INSERT INTO `T`
" + "(VALUES (ROW((NEXT VALUE FOR `MY_SEQ`))), (ROW((CURRENT VALUE FOR `MY_SEQ`))))");
    sql("insert into t values (1, current value for my_seq)").ok("INSERT INTO `T`
" + "(VALUES (ROW(1, (CURRENT VALUE FOR `MY_SEQ`))))");
}

