@Test
public void testCase() {
    tester.setFor(SqlStdOperatorTable.CASE);
    tester.checkScalarExact("case when 'a'='a' then 1 end", "1");
    tester.checkString("case 2 when 1 then 'a' when 2 then 'bcd' end", "bcd", "CHAR(3)");
    tester.checkString("case 1 when 1 then 'a' when 2 then 'bcd' end", "a  ", "CHAR(3)");
    tester.checkString("case 1 when 1 then cast('a' as varchar(1)) " + "when 2 then cast('bcd' as varchar(3)) end", "a", "VARCHAR(3)");
    if (DECIMAL) {
        tester.checkScalarExact("case 2 when 1 then 11.2 when 2 then 4.543 else null end", "DECIMAL(5, 3)", "4.543");
        tester.checkScalarExact("case 1 when 1 then 11.2 when 2 then 4.543 else null end", "DECIMAL(5, 3)", "11.200");
    }
    tester.checkScalarExact("case 'a' when 'a' then 1 end", "1");
    tester.checkScalarApprox("case 1 when 1 then 11.2e0 when 2 then cast(4 as bigint) else 3 end", "DOUBLE NOT NULL", 11.2, 0);
    tester.checkScalarApprox("case 1 when 1 then 11.2e0 when 2 then 4 else null end", "DOUBLE", 11.2, 0);
    tester.checkScalarApprox("case 2 when 1 then 11.2e0 when 2 then 4 else null end", "DOUBLE", 4, 0);
    tester.checkScalarApprox("case 1 when 1 then 11.2e0 when 2 then 4.543 else null end", "DOUBLE", 11.2, 0);
    tester.checkScalarApprox("case 2 when 1 then 11.2e0 when 2 then 4.543 else null end", "DOUBLE", 4.543, 0);
    tester.checkNull("case 'a' when 'b' then 1 end");
    // Per spec, 'case x when y then ...'
    // translates to 'case when x = y then ...'
    // so nulls do not match.
    // (Unlike Oracle's 'decode(null, null, ...)', by the way.)
    tester.checkString("case cast(null as int) when cast(null as int) then 'nulls match' else 'nulls do not match' end", "nulls do not match", "CHAR(18) NOT NULL");
    tester.checkScalarExact("case when 'a'=cast(null as varchar(1)) then 1 else 2 end", "2");
    // equivalent to "nullif('a',cast(null as varchar(1)))"
    tester.checkString("case when 'a' = cast(null as varchar(1)) then null else 'a' end", "a", "CHAR(1)");
    if (TODO) {
        tester.checkScalar("case 1 when 1 then row(1,2) when 2 then row(2,3) end", "ROW(INTEGER NOT NULL, INTEGER NOT NULL)", "row(1,2)");
        tester.checkScalar("case 1 when 1 then row('a','b') when 2 then row('ab','cd') end", "ROW(CHAR(2) NOT NULL, CHAR(2) NOT NULL)", "row('a ','b ')");
    }
    // multiple values in some cases (introduced in SQL:2011)
    tester.checkString("case 1 " + "when 1, 2 then '1 or 2' " + "when 2 then 'not possible' " + "when 3, 2 then '3' " + "else 'none of the above' " + "end", "1 or 2           ", "CHAR(17) NOT NULL");
    tester.checkString("case 2 " + "when 1, 2 then '1 or 2' " + "when 2 then 'not possible' " + "when 3, 2 then '3' " + "else 'none of the above' " + "end", "1 or 2           ", "CHAR(17) NOT NULL");
    tester.checkString("case 3 " + "when 1, 2 then '1 or 2' " + "when 2 then 'not possible' " + "when 3, 2 then '3' " + "else 'none of the above' " + "end", "3                ", "CHAR(17) NOT NULL");
    tester.checkString("case 4 " + "when 1, 2 then '1 or 2' " + "when 2 then 'not possible' " + "when 3, 2 then '3' " + "else 'none of the above' " + "end", "none of the above", "CHAR(17) NOT NULL");
    // TODO: Check case with multisets
}

