@Test
public void testOrOperatorLazy() {
    tester.setFor(SqlStdOperatorTable.OR);
    // need to evaluate 2nd argument if first evaluates to null, therefore
    // get error
    tester.check("values 1 < cast(null as integer) or sqrt(-4) = -2", SqlTests.BOOLEAN_TYPE_CHECKER, new ValueOrExceptionResultChecker(null, INVALID_ARG_FOR_POWER, CODE_2201F));
    // Do not need to evaluate 2nd argument if first evaluates to true.
    // In eager evaluation, get error;
    // lazy evaluation returns true;
    // both are valid.
    tester.check("values 1 < 2 or sqrt(-4) = -2", SqlTests.BOOLEAN_TYPE_CHECKER, new ValueOrExceptionResultChecker(Boolean.TRUE, INVALID_ARG_FOR_POWER, CODE_2201F));
    // NULL OR FALSE --> NULL
    // In eager evaluation, get error;
    // lazy evaluation returns NULL;
    // both are valid.
    tester.check("values 1 < cast(null as integer) or sqrt(4) = -2", SqlTests.BOOLEAN_TYPE_CHECKER, new ValueOrExceptionResultChecker(null, INVALID_ARG_FOR_POWER, CODE_2201F));
    // NULL OR TRUE --> TRUE
    tester.checkBoolean("1 < cast(null as integer) or sqrt(4) = 2", Boolean.TRUE);
}

