    tester.checkNull("overlay(cast(null as varchar(1)) placing 'abc' from 1)");
    tester.checkString("overlay(x'ABCdef' placing x'abcd' from 1)", "abcdef", "VARBINARY(5) NOT NULL");
    tester.checkString("overlay(x'ABCDEF1234' placing x'2345' from 1 for 2)", "2345ef1234", "VARBINARY(7) NOT NULL");
    if (enable) {
        tester.checkString("overlay(cast(x'ABCdef' as varbinary(5)) placing " + "cast(x'abcd' as binary(3)) from 1 for 2)", "abc  Cdef", "VARBINARY(8) NOT NULL");
    }
