    }
    tester.checkNull("overlay(x'ABCdef' placing x'abcd' from 1 for cast(null as integer))");
    tester.checkNull("overlay(cast(null as varbinary(1)) placing x'abcd' from 1)");
    tester.checkNull("overlay(x'abcd' placing x'abcd' from cast(null as integer))");
}

