    assertEquals(Aggregate.Group.SIMPLE, Aggregate.Group.induce(groupSet, groupSets));
    groupSets = Lists.newArrayList();
    assertEquals(Aggregate.Group.OTHER, Aggregate.Group.induce(groupSet, groupSets));
}

