/**
 * Tests a modifiable view.
 */
@Test
public void testModelWithModifiableView() throws Exception {
    final List<Employee> employees = new ArrayList<>();
    employees.add(new Employee(135, 10, "Simon", 56.7f, null));
    try (final TryThreadLocal.Memo ignore = EmpDeptTableFactory.THREAD_COLLECTION.push(employees)) {
        final CalciteAssert.AssertThat with = modelWithView("select \"name\", \"empid\" as e, \"salary\" " + "from \"MUTABLE_EMPLOYEES\" where \"deptno\" = 10", null);
        with.query("select \"name\" from \"adhoc\".V order by \"name\"").returns("name=Simon\n");
        with.doWithConnection(new Function<CalciteConnection, Object>() {

            @Override
            public Object apply(CalciteConnection input) {
                try {
                    final Statement statement = input.createStatement();
                    ResultSet resultSet = statement.executeQuery("explain plan for\n" + "insert into \"adhoc\".V\n" + "values ('Fred', 56, 123.4)");
                    assertThat(resultSet.next(), is(true));
                    assertThat(Util.toLinux(resultSet.getString(1)), is("EnumerableTableModify(table=[[adhoc, MUTABLE_EMPLOYEES]], operation=[INSERT], updateColumnList=[[]], flattened=[false])\n" + "  EnumerableCalc(expr#0..2=[{inputs}], expr#3=[CAST($t1):JavaType(int) NOT NULL], expr#4=[10], expr#5=[CAST($t0):JavaType(class java.lang.String)], expr#6=[CAST($t2):JavaType(float) NOT NULL], expr#7=[null], empid=[$t3], deptno=[$t4], name=[$t5], salary=[$t6], commission=[$t7])\n" + "    EnumerableValues(tuples=[[{ 'Fred', 56, 123.4 }]])\n"));
                    // With named columns
                    resultSet = statement.executeQuery("explain plan for\n" + "insert into \"adhoc\".V (\"name\", e, \"salary\")\n" + "values ('Fred', 56, 123.4)");
                    assertThat(resultSet.next(), is(true));
                    // With named columns, in different order
                    resultSet = statement.executeQuery("explain plan for\n" + "insert into \"adhoc\".V (e, \"salary\", \"name\")\n" + "values (56, 123.4, 'Fred')");
                    assertThat(resultSet.next(), is(true));
                    // Mis-named column
                    try {
                        final PreparedStatement s = input.prepareStatement("explain plan for\n" + "insert into \"adhoc\".V (empno, \"salary\", \"name\")\n" + "values (56, 123.4, 'Fred')");
                        fail("expected error, got " + s);
                    } catch (SQLException e) {
                        assertThat(e.getMessage(), startsWith("Error while preparing statement"));
                    }
                    // Fail to provide mandatory column
                    try {
                        final PreparedStatement s = input.prepareStatement("explain plan for\n" + "insert into \"adhoc\".V (e, name)\n" + "values (56, 'Fred')");
                        fail("expected error, got " + s);
                    } catch (SQLException e) {
                        assertThat(e.getMessage(), startsWith("Error while preparing statement"));
                    }
                    statement.close();
                    return null;
                } catch (SQLException e) {
                    throw Throwables.propagate(e);
                }
            }
        });
    }
}

/**
 * Tests a few cases where modifiable views are invalid.
 */
@Test
public void testModelWithInvalidModifiableView() throws Exception {
    final List<Employee> employees = new ArrayList<>();
    employees.add(new Employee(135, 10, "Simon", 56.7f, null));
    try (final TryThreadLocal.Memo ignore = EmpDeptTableFactory.THREAD_COLLECTION.push(employees)) {
        Util.discard(RESOURCE.noValueSuppliedForViewColumn(null, null));
        modelWithView("select \"name\", \"empid\" as e, \"salary\" " + "from \"MUTABLE_EMPLOYEES\" where \"commission\" = 10", true).query("select \"name\" from \"adhoc\".V order by \"name\"").throws_("View is not modifiable. No value is supplied for NOT NULL " + "column 'deptno' of base table 'MUTABLE_EMPLOYEES'");
        // no error if we do not claim that the view is modifiable
        modelWithView("select \"name\", \"empid\" as e, \"salary\" " + "from \"MUTABLE_EMPLOYEES\" where \"commission\" = 10", null).query("select \"name\" from \"adhoc\".V order by \"name\"").runs();
        modelWithView("select \"name\", \"empid\" as e, \"salary\" " + "from \"MUTABLE_EMPLOYEES\" where \"deptno\" IN (10, 20)", true).query("select \"name\" from \"adhoc\".V order by \"name\"").throws_("View is not modifiable. No value is supplied for NOT NULL " + "column 'deptno' of base table 'MUTABLE_EMPLOYEES'");
        // Deduce "deptno = 10" from the constraint, and add a further
        // condition "deptno < 20 OR commission > 1000".
        modelWithView("select \"name\", \"empid\" as e, \"salary\" " + "from \"MUTABLE_EMPLOYEES\"\n" + "where \"deptno\" = 10 AND (\"deptno\" < 20 OR \"commission\" > 1000)", true).query("insert into \"adhoc\".v values ('n',1,2)").explainContains("" + "EnumerableTableModify(table=[[adhoc, MUTABLE_EMPLOYEES]], operation=[INSERT], updateColumnList=[[]], flattened=[false])\n" + "  EnumerableCalc(expr#0..2=[{inputs}], expr#3=[CAST($t1):JavaType(int) NOT NULL], expr#4=[10], expr#5=[CAST($t0):JavaType(class java.lang.String)], expr#6=[CAST($t2):JavaType(float) NOT NULL], expr#7=[null], expr#8=[20], expr#9=[<($t4, $t8)], expr#10=[1000], expr#11=[>($t7, $t10)], expr#12=[OR($t9, $t11)], empid=[$t3], deptno=[$t4], name=[$t5], salary=[$t6], commission=[$t7], $condition=[$t12])\n" + "    EnumerableValues(tuples=[[{ 'n', 1, 2 }]])");
        modelWithView("select \"name\", \"empid\" as e, \"salary\" " + "from \"MUTABLE_EMPLOYEES\"\n" + "where \"commission\" = 100 AND \"deptno\" = 20", true).query("select \"name\" from \"adhoc\".V order by \"name\"").runs();
        modelWithView("select \"name\", \"empid\" as e, \"salary\", \"empid\" + 3 as e3, 1 as one\n" + "from \"MUTABLE_EMPLOYEES\"\n" + "where \"commission\" = 100 AND \"deptno\" = 20", true).query("select \"name\" from \"adhoc\".V order by \"name\"").runs();
        Util.discard(RESOURCE.moreThanOneMappedColumn(null, null));
        modelWithView("select \"name\", \"empid\" as e, \"salary\", \"name\" as n2 " + "from \"MUTABLE_EMPLOYEES\" where \"deptno\" IN (10, 20)", true).query("select \"name\" from \"adhoc\".V order by \"name\"").throws_("View is not modifiable. More than one expression maps to " + "column 'name' of base table 'MUTABLE_EMPLOYEES'");
        // no error if we do not claim that the view is modifiable
        modelWithView("select \"name\", \"empid\" as e, \"salary\", \"name\" as n2 " + "from \"MUTABLE_EMPLOYEES\" where \"deptno\" IN (10, 20)", null).query("select \"name\" from \"adhoc\".V order by \"name\"").runs();
    }
}

