/**
 * Tests accessing columns by name.
 */
@Test
public void testGetByName() throws Exception {
    // JDBC 3.0 specification: "Column names supplied to getter methods are case
    // insensitive. If a select list contains the same column more than once,
    // the first instance of the column will be returned."
    CalciteAssert.that().doWithConnection(new Function<CalciteConnection, Object>() {

        public Object apply(CalciteConnection c) {
            try {
                Statement s = c.createStatement();
                ResultSet rs = s.executeQuery("" + "SELECT 1 as \"a\", 2 as \"b\", 3 as \"a\", 4 as \"B\"\n" + "FROM (VALUES (0))");
                assertTrue(rs.next());
                assertEquals(1, rs.getInt("a"));
                assertEquals(1, rs.getInt("A"));
                assertEquals(2, rs.getInt("b"));
                assertEquals(2, rs.getInt("B"));
                assertEquals(1, rs.getInt(1));
                assertEquals(2, rs.getInt(2));
                assertEquals(3, rs.getInt(3));
                assertEquals(4, rs.getInt(4));
                try {
                    int x = rs.getInt("z");
                    fail("expected error, got " + x);
                } catch (SQLException e) {
                    // ok
                }
                assertEquals(1, rs.findColumn("a"));
                assertEquals(1, rs.findColumn("A"));
                assertEquals(2, rs.findColumn("b"));
                assertEquals(2, rs.findColumn("B"));
                try {
                    int x = rs.findColumn("z");
                    fail("expected error, got " + x);
                } catch (SQLException e) {
                    assertThat(e.getMessage(), equalTo("column 'z' not found"));
                }
                try {
                    int x = rs.getInt(0);
                    fail("expected error, got " + x);
                } catch (SQLException e) {
                    assertThat(e.getMessage(), equalTo("invalid column ordinal: 0"));
                }
                try {
                    int x = rs.getInt(5);
                    fail("expected error, got " + x);
                } catch (SQLException e) {
                    assertThat(e.getMessage(), equalTo("invalid column ordinal: 5"));
                }
                return null;
            } catch (SQLException e) {
                throw new RuntimeException(e);
            }
        }
    });
}

