            }
        }
    });
}

/**
 * Tests a {@link PreparedStatement} with parameters.
 */
@Test
public void testPreparedStatement() throws Exception {
    CalciteAssert.hr().doWithConnection(new Function<CalciteConnection, Object>() {

        public Object apply(CalciteConnection connection) {
            try {
                final PreparedStatement preparedStatement = connection.prepareStatement("select \"deptno\", \"name\" " + "from \"hr\".\"emps\"\n" + "where \"deptno\" < ? and \"name\" like ?");
                // execute with vars unbound - gives error
                ResultSet resultSet;
                try {
                    resultSet = preparedStatement.executeQuery();
                    fail("expected error, got " + resultSet);
                } catch (SQLException e) {
                    assertThat(e.getMessage(), equalTo("exception while executing query: unbound parameter"));
                }
                // execute with both vars null - no results
                preparedStatement.setNull(1, java.sql.Types.INTEGER);
                preparedStatement.setNull(2, java.sql.Types.VARCHAR);
                resultSet = preparedStatement.executeQuery();
                assertFalse(resultSet.next());
                // execute with ?0=15, ?1='%' - 3 rows
                preparedStatement.setInt(1, 15);
                preparedStatement.setString(2, "%");
                resultSet = preparedStatement.executeQuery();
                assertEquals("deptno=10; name=Bill\n" + "deptno=10; name=Sebastian\n" + "deptno=10; name=Theodore\n", CalciteAssert.toString(resultSet));
                // execute with ?0=15 (from last bind), ?1='%r%' - 1 row
                preparedStatement.setString(2, "%r%");
                resultSet = preparedStatement.executeQuery();
                assertEquals("deptno=10; name=Theodore\n", CalciteAssert.toString(resultSet));
                resultSet.close();
                preparedStatement.close();
                return null;
            } catch (SQLException e) {
                throw new RuntimeException(e);
            }
        }
    });
}

