/**
 * Tests that {@link Hook#PARSE_TREE} works.
 */
@Test
public void testHook() {
    final int[] callCount = { 0 };
    final Hook.Closeable hook = Hook.PARSE_TREE.addThread(new Function<Object[], Object>() {

        public Void apply(Object[] args) {
            assertThat(args.length, equalTo(2));
            assertThat(args[0], instanceOf(String.class));
            assertThat((String) args[0], equalTo("select \"deptno\", \"commission\", sum(\"salary\") s\n" + "from \"hr\".\"emps\"\n" + "group by \"deptno\", \"commission\""));
            assertThat(args[1], instanceOf(SqlSelect.class));
            ++callCount[0];
            return null;
        }
    });
    try {
        // Simple query does not run the hook.
        testSimple();
        assertThat(callCount[0], equalTo(0));
        // Non-trivial query runs hook once.
        testGroupByNull();
        assertThat(callCount[0], equalTo(1));
    } finally {
        hook.close();
    }
}

