    //   LOAD 'EMPS.csv'
    final PigRelBuilder builder = PigRelBuilder.create(config().build());
    final RelNode root = builder.load("EMP.csv", null, null).build();
    assertThat(str(root), is("LogicalTableScan(table=[[scott, EMP]])\n"));
}

