    rel.explain(planWriter);
    pw.flush();
    TestUtil.assertEqualsVerbose("<RelNode type="LogicalProject">
" + "	<Property name="EXPR$0">
" + "		+(1, 2)	</Property>
" + "	<Property name="EXPR$1">
" + "		3	</Property>
" + "	<Inputs>
" + "		<RelNode type="LogicalValues">
" + "			<Property name="tuples">
" + "				[{ true }]			</Property>
" + "			<Inputs/>
" + "		</RelNode>
" + "	</Inputs>
" + "</RelNode>
", Util.toLinux(sw.toString()));
}

