@Test
public void testIntervalTimeUnitEnumeration() {
    // Since there is validation code relaying on the fact that the
    // enumerated time unit ordinals in SqlIntervalQualifier starts with 0
    // and ends with 5, this test is here to make sure that if someone
    // changes how the time untis are setup, an early feedback will be
    // generated by this test.
    assertEquals(0, TimeUnit.YEAR.ordinal());
    assertEquals(1, TimeUnit.MONTH.ordinal());
    assertEquals(2, TimeUnit.DAY.ordinal());
    assertEquals(3, TimeUnit.HOUR.ordinal());
    assertEquals(4, TimeUnit.MINUTE.ordinal());
    assertEquals(5, TimeUnit.SECOND.ordinal());
    boolean b = (TimeUnit.YEAR.ordinal() < TimeUnit.MONTH.ordinal()) && (TimeUnit.MONTH.ordinal() < TimeUnit.DAY.ordinal()) && (TimeUnit.DAY.ordinal() < TimeUnit.HOUR.ordinal()) && (TimeUnit.HOUR.ordinal() < TimeUnit.MINUTE.ordinal()) && (TimeUnit.MINUTE.ordinal() < TimeUnit.SECOND.ordinal());
    assertTrue(b);
}

