    checkExpType("timestampdiff(SQL_TSI_WEEK, cast(null as timestamp), current_timestamp)", "INTEGER");
    checkWholeExpFails("timestampadd(incorrect, 1, current_timestamp)", "(?s).*Was expecting one of.*");
    checkWholeExpFails("timestampdiff(incorrect, current_timestamp, current_timestamp)", "(?s).*Was expecting one of.*");
}

