@Test
public void testAmbiguousColumn() {
    checkFails("select * from emp join dept\n" + " on emp.deptno = ^deptno^", "Column 'DEPTNO' is ambiguous");
    // this is ok
    check("select * from emp as e\n" + " join dept as d\n" + " on e.deptno = d.deptno");
    // fail: ambiguous column in WHERE
    checkFails("select * from emp as emps, dept\n" + "where ^deptno^ > 5", "Column 'DEPTNO' is ambiguous");
    // fail: alias 'd' obscures original table name 'dept'
    checkFails("select * from emp as emps, dept as d\n" + "where ^dept^.deptno > 5", "Table 'DEPT' not found");
    // fail: ambiguous column reference in ON clause
    checkFails("select * from emp as e\n" + " join dept as d\n" + " on e.deptno = ^deptno^", "Column 'DEPTNO' is ambiguous");
    // ok: column 'comm' is unambiguous
    check("select * from emp as e\n" + " join dept as d\n" + " on e.deptno = comm");
    // ok: reference to derived column
    check("select * from dept\n" + " join (select mod(comm, 30) as commmod from emp)\n" + "on deptno = commmod");
    // fail: deptno is ambiguous
    checkFails("select name from dept\n" + "join (select mod(comm, 30) as commmod, deptno from emp)\n" + "on ^deptno^ = commmod", "Column 'DEPTNO' is ambiguous");
    // fail: lateral reference
    checkFails("select * from emp as e,\n" + " (select 1, ^e^.deptno from (values(true))) as d", "Table 'E' not found");
}

