/**
 * Parser allows "*" in FROM clause because "*" can occur in any identifier.
 * But validator must not.
 *
 * @see #testStarIdentifier()
 */
@Test
public void testStarInFromFails() {
    sql("select emp.empno AS x from ^sales.*^").fails("Table 'SALES.\\*' not found");
    sql("select emp.empno from emp where emp.^*^ is not null").fails("Unknown field '\\*'");
}

@Test
public void testStarDotIdFails() {
    // Parser allows a star inside (not at end of) compound identifier, but
    // validator does not
    sql("select emp.^*^.foo from emp").fails("Column '\\*' not found in table 'EMP'");
    // Parser does not allow star dot identifier.
    sql("select ^*^.foo from emp").fails("(?s).*Encountered \".\" at .*");
}

@Test
public void testAsColumnList() {
    check("select d.a, b from dept as d(a, b)");
    checkFails("select d.^deptno^ from dept as d(a, b)", "(?s).*Column 'DEPTNO' not found in table 'D'.*");
    checkFails("select 1 from dept as d(^a, b, c^)", "(?s).*List of column aliases must have same degree as table; " + "table has 2 columns \\('DEPTNO', 'NAME'\\), " + "whereas alias list has 3 columns.*");
    checkResultType("select * from dept as d(a, b)", "RecordType(INTEGER NOT NULL A, VARCHAR(10) NOT NULL B) NOT NULL");
    checkResultType("select * from (values ('a', 1), ('bc', 2)) t (a, b)", "RecordType(CHAR(2) NOT NULL A, INTEGER NOT NULL B) NOT NULL");
}

@Test
public void testInList() {
    check("select * from emp where empno in (10,20)");
    // "select * from emp where empno in ()" is invalid -- see parser test
    check("select * from emp\n" + "where empno in (10 + deptno, cast(null as integer))");
    checkFails("select * from emp where empno in ^(10, '20')^", ERR_IN_VALUES_INCOMPATIBLE);
    checkExpType("1 in (2, 3, 4)", "BOOLEAN NOT NULL");
    checkExpType("cast(null as integer) in (2, 3, 4)", "BOOLEAN");
    checkExpType("1 in (2, cast(null as integer) , 4)", "BOOLEAN");
    checkExpType("1 in (2.5, 3.14)", "BOOLEAN NOT NULL");
    checkExpType("true in (false, unknown)", "BOOLEAN");
    checkExpType("true in (false, false or unknown)", "BOOLEAN");
    checkExpType("true in (false, true)", "BOOLEAN NOT NULL");
    checkExpType("(1,2) in ((1,2), (3,4))", "BOOLEAN NOT NULL");
    checkExpType("'medium' in (cast(null as varchar(10)), 'bc')", "BOOLEAN");
    // nullability depends on nullability of both sides
    checkColumnType("select empno in (1, 2) from emp", "BOOLEAN NOT NULL");
    checkColumnType("select nullif(empno,empno) in (1, 2) from emp", "BOOLEAN");
    checkColumnType("select empno in (1, nullif(empno,empno), 2) from emp", "BOOLEAN");
    checkExpFails("1 in ^(2, 'c')^", ERR_IN_VALUES_INCOMPATIBLE);
    checkExpFails("1 in ^((2), (3,4))^", ERR_IN_VALUES_INCOMPATIBLE);
    checkExp("false and ^1 in ('b', 'c')^");
    checkExpFails("false and ^1 in (date '2012-01-02', date '2012-01-04')^", ERR_IN_OPERANDS_INCOMPATIBLE);
    checkExpFails("1 > 5 ^or (1, 2) in (3, 4)^", ERR_IN_OPERANDS_INCOMPATIBLE);
}

