@Test
public void testDuplicateTableAliasFails() {
    // implicit alias clashes with implicit alias
    checkFails("select 1 from emp, ^emp^", "Duplicate relation name 'EMP' in FROM clause");
    // implicit alias clashes with implicit alias, using join syntax
    checkFails("select 1 from emp join ^emp^ on emp.empno = emp.mgrno", "Duplicate relation name 'EMP' in FROM clause");
    // explicit alias clashes with implicit alias
    checkFails("select 1 from emp join ^dept as emp^ on emp.empno = emp.deptno", "Duplicate relation name 'EMP' in FROM clause");
    // implicit alias does not clash with overridden alias
    check("select 1 from emp as e join emp on emp.empno = e.deptno");
    // explicit alias does not clash with overridden alias
    check("select 1 from emp as e join dept as emp on e.empno = emp.deptno");
    // more than 2 in from clause
    checkFails("select 1 from emp, dept, emp as e, ^dept as emp^, emp", "Duplicate relation name 'EMP' in FROM clause");
    // alias applied to subquery
    checkFails("select 1 from emp, (^select 1 as x from (values (true))) as emp^", "Duplicate relation name 'EMP' in FROM clause");
    checkFails("select 1 from emp, (^values (true,false)) as emp (b, c)^, dept as emp", "Duplicate relation name 'EMP' in FROM clause");
    // alias applied to table function. doesn't matter that table fn
    // doesn't exist - should find the alias problem first
    checkFails("select 1 from emp, ^table(foo()) as emp^", "Duplicate relation name 'EMP' in FROM clause");
    // explicit table
    checkFails("select 1 from emp, ^(table foo.bar.emp) as emp^", "Duplicate relation name 'EMP' in FROM clause");
    // alias does not clash with alias inherited from enclosing context
    check("select 1 from emp, dept where exists (\n" + "  select 1 from emp where emp.empno = emp.deptno)");
}

@Test
public void testSchemaTableStar() {
    sql("select ^sales.e^.* from sales.emp as e").fails("Unknown identifier 'SALES\\.E'");
    sql("select sales.dept.* from sales.dept").type("RecordType(INTEGER NOT NULL DEPTNO," + " VARCHAR(10) NOT NULL NAME) NOT NULL");
    sql("select sales.emp.* from emp").ok();
    sql("select sales.emp.* from emp as emp").ok();
    // MySQL gives: "Unknown table 'emp'"
    // (consistent with MySQL)
    sql("select ^sales.emp^.* from emp as e").fails("Unknown identifier 'SALES.EMP'");
}

@Test
public void testSchemaTableColumn() {
    sql("select emp.empno from sales.emp").ok();
    sql("select sales.emp.empno from sales.emp").ok();
    sql("select sales.emp.empno from sales.emp\n" + "where sales.emp.deptno > 0").ok();
    sql("select 1 from sales.emp where sales.emp.^bad^ < 0").fails("Column 'BAD' not found in table 'SALES.EMP'");
    sql("select ^sales.bad^.empno from sales.emp\n" + "where sales.emp.deptno > 0").fails("Table 'SALES\\.BAD' not found");
    sql("select sales.emp.deptno from sales.emp").ok();
    sql("select 1 from sales.emp where sales.emp.deptno = 10").ok();
    sql("select 1 from sales.emp order by sales.emp.deptno").ok();
    // alias does not hide the fully-qualified name if same
    // (consistent with MySQL)
    sql("select sales.emp.deptno from sales.emp as emp").ok();
    // alias hides the fully-qualified name
    // (consistent with MySQL)
    sql("select ^sales.emp^.deptno from sales.emp as e").fails("Table 'SALES\\.EMP' not found");
    sql("select sales.emp.deptno from sales.emp, ^sales.emp^").fails("Duplicate relation name 'EMP' in FROM clause");
    // Table exists but not used in FROM clause
    sql("select ^sales.emp^.deptno from sales.dept as d1, sales.dept").fails("Table 'SALES.EMP' not found");
    // Table does not exist
    sql("select ^sales.bad^.deptno from sales.dept as d1, sales.dept").fails("Table 'SALES.BAD' not found");
}

