/**
 * Tests the {@code WITH} clause, also called common table expressions.
 */
@Test
public void testWith() {
    // simplest possible
    checkResultType("with emp2 as (select * from emp)\n" + "select * from emp2", EMP_RECORD_TYPE);
    // degree of emp2 column list does not match its query
    checkFails("with emp2 ^(x, y)^ as (select * from emp)\n" + "select * from emp2", "Number of columns must match number of query columns");
    // duplicate names in column list
    checkFails("with emp2 (x, y, ^y^, x) as (select sal, deptno, ename, empno from emp)\n" + "select * from emp2", "Duplicate name 'Y' in column list");
    // column list required if aliases are not unique
    checkFails("with emp2 as (^select empno as e, sal, deptno as e from emp^)\n" + "select * from emp2", "Column has duplicate column name 'E' and no column list specified");
    // forward reference
    checkFails("with emp3 as (select * from ^emp2^),\n" + " emp2 as (select * from emp)\n" + "select * from emp3", "Table 'EMP2' not found");
    // forward reference in with-item not used; should still fail
    checkFails("with emp3 as (select * from ^emp2^),\n" + " emp2 as (select * from emp)\n" + "select * from emp2", "Table 'EMP2' not found");
    // table not used is ok
    checkResultType("with emp2 as (select * from emp),\n" + " emp3 as (select * from emp2)\n" + "select * from emp2", EMP_RECORD_TYPE);
    // self-reference is not ok, even in table not used
    checkFails("with emp2 as (select * from emp),\n" + " emp3 as (select * from ^emp3^)\n" + "values (1)", "Table 'EMP3' not found");
    // self-reference not ok
    checkFails("with emp2 as (select * from ^emp2^)\n" + "select * from emp2 where false", "Table 'EMP2' not found");
    // refer to 2 previous tables, not just immediately preceding
    checkResultType("with emp2 as (select * from emp),\n" + " dept2 as (select * from dept),\n" + " empDept as (select emp2.empno, dept2.deptno from dept2 join emp2 using (deptno))\n" + "select 1 as one from empDept", "RecordType(INTEGER NOT NULL ONE) NOT NULL");
}

