/**
 * Tests validation of the ORDER BY clause when GROUP BY is present.
 */
@Test
public void testOrderGroup() {
    // Group by
    checkFails("select 1 from emp group by deptno order by ^empno^", "Expression 'EMP\\.EMPNO' is not being grouped");
    // order by can contain aggregate expressions
    check("select empno from emp " + "group by empno, deptno " + "order by deptno * sum(sal + 2)");
    // Having
    checkFails("select sum(sal) from emp having count(*) > 3 order by ^empno^", "Expression 'EMP\\.EMPNO' is not being grouped");
    check("select sum(sal) from emp having count(*) > 3 order by sum(deptno)");
    // Select distinct
    checkFails("select distinct deptno from emp group by deptno order by ^empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    checkFails("select distinct deptno from emp group by deptno order by deptno, ^empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    check("select distinct deptno from emp group by deptno order by deptno");
    // UNION of SELECT DISTINCT and GROUP BY behaves just like a UNION.
    check("select distinct deptno from dept " + "union all " + "select empno from emp group by deptno, empno " + "order by deptno");
    // order by can contain a mixture of aliases and aggregate expressions
    check("select empno as x " + "from emp " + "group by empno, deptno " + "order by x * sum(sal + 2)");
    sql("select empno as x " + "from emp " + "group by empno, deptno " + "order by empno * sum(sal + 2)").failsIf(tester.getConformance().isSortByAliasObscures(), "xxxx");
}

/**
 * Tests validation of the ORDER BY clause when DISTINCT is present.
 */
@Test
public void testOrderDistinct() {
    // Distinct on expressions with attempts to order on a column in
    // the underlying table
    checkFails("select distinct cast(empno as bigint) " + "from emp order by ^empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    checkFails("select distinct cast(empno as bigint) " + "from emp order by ^emp.empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    checkFails("select distinct cast(empno as bigint) as empno " + "from emp order by ^emp.empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    checkFails("select distinct cast(empno as bigint) as empno " + "from emp as e order by ^e.empno^", "Expression 'E\\.EMPNO' is not in the select clause");
    // These tests are primarily intended to test cases where sorting by
    // an alias is allowed.  But for instances that don't support sorting
    // by alias, the tests also verify that a proper exception is thrown.
    sql("select distinct cast(empno as bigint) as empno " + "from emp order by ^empno^").failsIf(!tester.getConformance().isSortByAlias(), "Expression 'EMPNO' is not in the select clause");
    sql("select distinct cast(empno as bigint) as eno " + "from emp order by ^eno^").failsIf(!tester.getConformance().isSortByAlias(), "Column 'ENO' not found in any table");
    sql("select distinct cast(empno as bigint) as empno " + "from emp e order by ^empno^").failsIf(!tester.getConformance().isSortByAlias(), "Expression 'EMPNO' is not in the select clause");
    // Distinct on expressions, sorting using ordinals.
    if (tester.getConformance().isSortByOrdinal()) {
        check("select distinct cast(empno as bigint) from emp order by 1");
        check("select distinct cast(empno as bigint) as empno " + "from emp order by 1");
        check("select distinct cast(empno as bigint) as empno " + "from emp as e order by 1");
    }
    // Distinct on expressions with ordering on expressions as well
    check("select distinct cast(empno as varchar(10)) from emp " + "order by cast(empno as varchar(10))");
    checkFails("select distinct cast(empno as varchar(10)) as eno from emp " + " order by upper(^eno^)", tester.getConformance().isSortByAlias() ? null : "Column 'ENO' not found in any table");
}

