@Test
public void testOrderGroupDistinct() {
    // Order by an aggregate function,
    // which exists in select-clause with distinct being present
    check("select distinct count(empno) AS countEMPNO from emp\n" + "group by empno\n" + "order by 1");
    check("select distinct count(empno) from emp\n" + "group by empno\n" + "order by 1");
    check("select distinct count(empno) AS countEMPNO from emp\n" + "group by empno\n" + "order by count(empno)");
    check("select distinct count(empno) from emp\n" + "group by empno\n" + "order by count(empno)");
    check("select distinct count(empno) from emp\n" + "group by empno\n" + "order by count(empno) desc");
    checkFails("SELECT DISTINCT deptno from emp\n" + "ORDER BY deptno, ^sum(empno)^", "Aggregate expression is illegal in ORDER BY clause of non-aggregating SELECT");
    checkFails("SELECT DISTINCT deptno from emp\n" + "GROUP BY deptno ORDER BY deptno, ^sum(empno)^", "Expression 'SUM\\(`EMP`\\.`EMPNO`\\)' is not in the select clause");
    checkFails("SELECT DISTINCT deptno, min(empno) from emp\n" + "GROUP BY deptno ORDER BY deptno, ^sum(empno)^", "Expression 'SUM\\(`EMP`\\.`EMPNO`\\)' is not in the select clause");
    check("SELECT DISTINCT deptno, sum(empno) from emp\n" + "GROUP BY deptno ORDER BY deptno, sum(empno)");
}

@Test
public void testGroup() {
    checkFails("select empno from emp where ^sum(sal)^ > 50", "Aggregate expression is illegal in WHERE clause");
    checkFails("select ^empno^ from emp group by deptno", "Expression 'EMPNO' is not being grouped");
    checkFails("select ^*^ from emp group by deptno", "Expression 'EMP\\.EMPNO' is not being grouped");
    // If we're grouping on ALL columns, 'select *' is ok.
    // Checked on Oracle10G.
    check("select * from (select empno,deptno from emp) group by deptno,empno");
    // This query tries to reference an agg expression from within a
    // subquery as a correlating expression, but the SQL syntax rules say
    // that the agg function SUM always applies to the current scope.
    // As it happens, the query is valid.
    check("select deptno\n" + "from emp\n" + "group by deptno\n" + "having exists (select sum(emp.sal) > 10 from (values(true)))");
    // if you reference a column from a subquery, it must be a group col
    check("select deptno " + "from emp " + "group by deptno " + "having exists (select 1 from (values(true)) where emp.deptno = 10)");
    // Needs proper error message text and error markers in query
    if (TODO) {
        checkFails("select deptno " + "from emp " + "group by deptno " + "having exists (select 1 from (values(true)) where emp.empno = 10)", "xx");
    }
    // constant expressions
    check("select cast(1 as integer) + 2 from emp group by deptno");
    check("select localtime, deptno + 3 from emp group by deptno");
}

