@Test
public void testGroupExpressionEquivalenceLiteral() {
    // The purpose of this test is to see whether the validator
    // regards a pair of constants as equivalent. If we just used the raw
    // constants the validator wouldn't care ('SELECT 1 FROM emp GROUP BY
    // 2' is legal), so we combine a column and a constant into the same
    // CASE expression.
    // literal equivalence
    check("select case empno when 10 then date '1969-04-29' else null end\n" + "from emp\n" + "group by case empno when 10 then date '1969-04-29' else null end");
    // this query succeeds in oracle 10.1 because 1 and 1.0 have the same
    // type
    checkFails("select case ^empno^ when 10 then 1 else null end from emp " + "group by case empno when 10 then 1.0 else null end", "Expression 'EMPNO' is not being grouped");
    // 3.1415 and 3.14150 are different literals (I don't care either way)
    checkFails("select case ^empno^ when 10 then 3.1415 else null end from emp " + "group by case empno when 10 then 3.14150 else null end", "Expression 'EMPNO' is not being grouped");
    // 3 and 03 are the same literal (I don't care either way)
    check("select case empno when 10 then 03 else null end from emp " + "group by case empno when 10 then 3 else null end");
    checkFails("select case ^empno^ when 10 then 1 else null end from emp " + "group by case empno when 10 then 2 else null end", "Expression 'EMPNO' is not being grouped");
    check("select case empno when 10 then timestamp '1969-04-29 12:34:56.0'\n" + "       else null end from emp\n" + "group by case empno when 10 then timestamp '1969-04-29 12:34:56' else null end");
}

