@Test
public void testNestedAggFails() {
    // simple case
    checkFails("select ^sum(max(empno))^ from emp", ERR_NESTED_AGG);
    // should still fail with intermediate expression
    checkFails("select ^sum(2*max(empno))^ from emp", ERR_NESTED_AGG);
    // make sure it fails with GROUP BY too
    checkFails("select ^sum(max(empno))^ from emp group by deptno", ERR_NESTED_AGG);
    // make sure it fails in HAVING too
    checkFails("select count(*) from emp group by deptno " + "having ^sum(max(empno))^=3", ERR_NESTED_AGG);
    // double-nesting should fail too; bottom-up validation currently
    // causes us to flag the intermediate level
    checkFails("select sum(^max(min(empno))^) from emp", ERR_NESTED_AGG);
    // in OVER clause
    checkFails("select ^sum(max(empno)) OVER^ (order by deptno ROWS 2 PRECEDING) from emp", ERR_NESTED_AGG);
    // OVER in clause
    checkFails("select ^sum(max(empno) OVER (order by deptno ROWS 2 PRECEDING))^ from emp", ERR_NESTED_AGG);
}

