        calciteConnection.getRootSchema().add("TEST", schema);
        final String sql = "select * from \"TEST\".\"DEPTS\" where \"NAME\" = ?";
        final PreparedStatement statement2 = calciteConnection.prepareStatement(sql);
        statement2.setString(1, "Sales");
