    String s = Linq4j.asEnumerable(depts).groupJoin(Linq4j.asEnumerable(emps).concat(Linq4j.asEnumerable(badEmps)), DEPT_DEPTNO_SELECTOR, EMP_DEPTNO_SELECTOR, new Function2<Department, Enumerable<Employee>, String>() {

        public String apply(Department v1, Enumerable<Employee> v2) {
            final StringBuilder buf = new StringBuilder("[");
            int n = 0;
            for (Employee employee : v2) {
                if (n++ > 0) {
                    buf.append(", ");
