/**
 * Test for {@link Primitive#sortArray(Object)}.
 */
@Test
public void testArraySort() {
    char[] chars = { 'm', 'o', 'n', 'o', 'l', 'a', 'k', 'e' };
    Primitive.CHAR.sortArray(chars);
    assertEquals("[a, e, k, l, m, n, o, o]", Primitive.CHAR.arrayToString(chars));
    // mixed true and false
    boolean[] booleans0 = { true, false, true, true, false };
    Primitive.BOOLEAN.sortArray(booleans0);
    assertEquals("[false, false, true, true, true]", Primitive.BOOLEAN.arrayToString(booleans0));
    // all false
    boolean[] booleans1 = { false, false, false, false, false };
    Primitive.BOOLEAN.sortArray(booleans1);
    assertEquals("[false, false, false, false, false]", Primitive.BOOLEAN.arrayToString(booleans1));
    // all true
    boolean[] booleans2 = { true, true, true, true, true };
    Primitive.BOOLEAN.sortArray(booleans2);
    assertEquals("[true, true, true, true, true]", Primitive.BOOLEAN.arrayToString(booleans2));
    // empty
    boolean[] booleans3 = {};
    Primitive.BOOLEAN.sortArray(booleans3);
    assertEquals("[]", Primitive.BOOLEAN.arrayToString(booleans3));
    // ranges specified
    boolean[] booleans4 = { true, true, false, false, true, false, false };
    Primitive.BOOLEAN.sortArray(booleans4, 1, 6);
    assertEquals("[true, false, false, false, true, true, false]", Primitive.BOOLEAN.arrayToString(booleans4));
}

@Test
public void testGcd() {
    int i = 0;
    char c = 0;
    byte b = 0;
    short s = 0;
    int l = 0;
    // int to long
    l = i;
    assertEquals(long.class, Types.gcd(int.class, long.class));
    // reverse args
    assertEquals(long.class, Types.gcd(long.class, int.class));
    // char to int
    i = c;
    assertEquals(int.class, Types.gcd(char.class, int.class));
    // can assign byte to short
    assertEquals(short.class, Types.gcd(byte.class, short.class));
    s = b;
    // cannot assign byte to char
    // cannot assign char to short
    // can assign byte and char to int
    // fails: c = b;
    // fails: s = c;
    i = b;
    i = c;
    assertEquals(int.class, Types.gcd(char.class, byte.class));
    assertEquals(int.class, Types.gcd(byte.class, char.class));
    // mix a primitive with an object
    // (correct answer is java.io.Serializable)
    assertEquals(Object.class, Types.gcd(String.class, int.class));
    java.io.Serializable o = true ? "x" : 1;
}

